<script setup lang="ts">
import {ref,computed,onBeforeUnmount,watch} from 'vue'
import SignalWater from './SignalWater.vue'
import {restoreSignal,signalCode,verifySignal,type Command,type Pulse,type SignalDraft} from './signal'
const props=defineProps<{context:string;initial?:SignalDraft;motion:boolean;audible:boolean}>()
const emit=defineEmits<{change:[value:SignalDraft];complete:[value:SignalDraft];drum:[]}>()
const state=ref(restoreSignal(props.initial)),sending=ref(-1),flashing=ref(false),dragging=ref(false),note=ref('先定要船队做什么，再把约定的两声号传出去。')
const markerPositions=ref([[56,47],[40,65]])
const north=computed(()=>props.context==='north'),names=['前船','后船']
const labels=computed(()=>north.value?{advance:'探近',spread:'分探',recall:'收队'}:{advance:'进舟',spread:'分队',recall:'收队'})
const descriptions=computed(()=>north.value?{advance:'哨艇靠前，查看草船',spread:'向两侧分探，查明来船',recall:'回寨集结，守住水门'}:{advance:'前船带路，后船跟进',spread:'两侧让开，留下行船水道',recall:'前船停桨，等后船靠拢'})
const ready=computed(()=>verifySignal(state.value)),wrong=computed(()=>state.value.command&&state.value.code.length===2&&JSON.stringify(state.value.code)!==JSON.stringify(signalCode(state.value.command)))
watch(state,()=>emit('change',JSON.parse(JSON.stringify(state.value))),{deep:true,flush:'sync'})
let timer:ReturnType<typeof setTimeout>,audio:AudioContext|undefined
const sequenceTimers=new Set<ReturnType<typeof setTimeout>>()
function later(fn:()=>void,ms:number){const id=setTimeout(()=>{sequenceTimers.delete(id);fn()},ms);sequenceTimers.add(id)}
function stopSequence(){sequenceTimers.forEach(clearTimeout);sequenceTimers.clear();flashing.value=false}
function choose(command:Command){stopSequence();clearTimeout(timer);sending.value=-1;state.value={...state.value,command,code:[],relays:[]};note.value=descriptions.value[command]+'。先敲出或揭出两道信号。'}
function channel(value:'sound'|'light'){if(sending.value>=0||state.value.relays.length)return;state.value.channel=value;state.value.code=[]}
function play(pulse:Pulse){if(!props.audible)return;if(state.value.channel==='sound'&&pulse==='short'){emit('drum');return}
 if(state.value.channel==='light')return
 try{audio??=new AudioContext();void audio.resume();const t=audio.currentTime;
 for(const [hz,weight] of [[146,.17],[237,.09],[389,.05],[623,.02]]){const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=hz;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(weight,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+1.5);o.start(t);o.stop(t+1.6);o.onended=()=>{o.disconnect();g.disconnect()}}}catch{}
}
function pulse(p:Pulse){if(!state.value.command||state.value.code.length>=2||sending.value>=0)return;state.value.code.push(p);play(p);flashing.value=true;clearTimeout(timer);timer=setTimeout(()=>flashing.value=false,p==='short'?220:650);note.value=state.value.code.length<2?'再补一道。':wrong.value?'韩伯：这两声合在一起，不是刚才约定的令。先听示范，再重发。':'号令已备。把灯拖向前船，或直接点前船传令。'}
function clearCode(){stopSequence();clearTimeout(timer);sending.value=-1;flashing.value=false;state.value.code=[];state.value.relays=[];note.value='重新编这一令，船队暂不行动。'}
function showCode(code:Pulse[]){stopSequence();code.forEach((p,i)=>later(()=>{play(p);flashing.value=true;later(()=>flashing.value=false,p==='short'?220:650)},i*850))}
function demonstration(){if(!state.value.command||sending.value>=0)return;note.value='约定：'+signalCode(state.value.command).map(x=>x==='short'?'短':'长').join(' · ')+'。照自己的节奏来，不比快慢。';showCode(signalCode(state.value.command))}
function send(i:number){dragging.value=false;if(sending.value>=0||ready.value||!state.value.command)return;
 if(state.value.code.length!==2||wrong.value){note.value='先把约定的两道号备齐。';return}
 if(i!==state.value.relays.length){note.value='后船还听不清，先由前船接号，再传到后船。';return}
 sending.value=i;note.value=names[i]+'正在辨号，等它复号再看船动。';showCode([...state.value.code])
 clearTimeout(timer);timer=setTimeout(()=>{const ship=names[i];state.value.relays.push({ship,code:[...state.value.code],ack:true});sending.value=-1;note.value=i===0?'前船回号：'+labels.value[state.value.command!]+'。把同一道令接着送到后船。':'两船回号一致。'+descriptions.value[state.value.command!]+'。';},props.motion?1600:200)
}
function drop(e:PointerEvent){if(!dragging.value)return;dragging.value=false;const el=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-ship]');if(el)send(Number(el.getAttribute('data-ship')))}
const positions=computed(()=>names.map((_,i)=>{
 const moved=state.value.relays.length>i,c=state.value.command
 return moved?(c==='advance'?[[55,32],[40,50]]:c==='spread'?[[27,39],[74,48]]:[[48,53],[56,62]])[i]:[[56,47],[40,65]][i]
}))
onBeforeUnmount(()=>{clearTimeout(timer);stopSequence();audio?.close()})
</script>
<template><section class="nav-signal" :class="{still:!motion}" @pointerup="drop" @pointercancel="dragging=false">
<div class="signal-sky" :style="{backgroundImage:'linear-gradient(#061522b8,#122b3b88),url(./v15/'+(north?'C_order':context==='close'?'near_order':'fleet_order')+'.webp)'}"></div><div class="signal-fog"></div>
<header><small>{{north?'曹寨 · 哨艇传令':context==='close'?'近寨 · 江上应变':'江心 · 领船传令'}}</small><h2>一道号，两船应</h2><p>{{note}}</p></header>
<div class="command-rail" aria-label="决定船队行动"><button v-for="c in (['advance','spread','recall'] as Command[])" :key="c" :aria-pressed="state.command===c" @click="choose(c)"><b>{{labels[c]}}</b><span>{{descriptions[c]}}</span><i>{{signalCode(c).map(p=>p==='short'?'●':'━━').join('　')}}</i></button></div>
<div class="river-plane" aria-label="等待军令的船队">
<SignalWater :positions="positions" :motion="motion" :north="north" @markers="markerPositions=$event"/><div class="far-bank">{{north?'北岸水门在身后':'北岸 · 曹寨'}}</div>
<svg class="signal-trails" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><path v-for="(p,i) in markerPositions" :d="'M 770 500 Q '+p[0]*10+' 500 '+p[0]*10+' '+p[1]*6" :class="{lit:sending===i||state.relays.length>i}"/></svg>
<button v-for="(ship,i) in names" :key="ship" class="signal-boat" :data-ship="i" :class="{answered:state.relays.length>i,answering:sending===i}" :style="{left:markerPositions[i][0]+'%',top:markerPositions[i][1]+'%'}" :aria-label="'向'+ship+'传令'" @click="send(i)">
<i class="boat-signal-light"></i><strong>{{ship}}</strong><small>{{sending===i?'正在复号…':state.relays.length>i?labels[state.command!]+' · 已收到':'候令'}}</small></button>
<div class="lead-seat"><span>领船</span><button class="hooded-lamp" :class="{flash:flashing,dragging}" @pointerdown.prevent="dragging=true" @keydown.enter.prevent="send(state.relays.length)" @keydown.space.prevent="send(state.relays.length)" aria-label="拖灯向船传令，回车向下一船传令"><i></i></button><small>{{dragging?'移到船上松手':'拖灯传号 · 也可点船'}}</small></div>
</div>
<footer><div class="signal-channel"><button :aria-pressed="state.channel==='light'" :disabled="sending>=0||state.relays.length>0" @click="channel('light')">遮灯传号</button><button :aria-pressed="state.channel==='sound'" :disabled="sending>=0||state.relays.length>0" @click="channel('sound')">鼓金传号</button><small>{{state.channel==='light'?'灯光指向同伴，也可能被对岸看见。':'声音传得远，对岸也听得到。'}}</small></div>
<div class="signal-instruments"><button :disabled="!state.command||state.code.length>=2" @click="pulse('short')">{{state.channel==='light'?'揭灯一下':'击鼓一声'}}<small>短</small></button><button :disabled="!state.command||state.code.length>=2" @click="pulse('long')">{{state.channel==='light'?'揭灯长亮':'鸣金一声'}}<small>长</small></button><div class="code-strip" aria-label="当前发出的信号">{{state.code.map(x=>x==='short'?'●':'━━').join('　')||'·　·'}}</div><button class="minor" :disabled="sending>=0" @click="demonstration">听看约定</button><button class="minor" @click="clearCode">重编这道号</button></div><button class="send-finish" :disabled="!ready" @click="emit('complete',JSON.parse(JSON.stringify(state)))">两船已应，查看江面 →</button><small class="signal-agreement">{{north?'短短探近 · 短长分探 · 长长收队':'短短进舟 · 短长分队 · 长长收队'}}</small></footer>
</section></template>
<style scoped>
.nav-signal{position:absolute;inset:0;overflow:hidden;background:#081a25;color:#e9e1cd;isolation:isolate;font-family:SimSun,serif}.signal-sky{position:absolute;inset:0;background:linear-gradient(#061522aa,#122b3b88),url('/v15/fleet_order.webp') center/cover;z-index:-3}.signal-fog{position:absolute;inset:20% -30%;background:radial-gradient(ellipse,#c3d8dc0e,transparent 63%);animation:mist 16s ease-in-out infinite alternate;z-index:-1;pointer-events:none}header{position:absolute;top:7%;left:4%;width:56%;z-index:4;pointer-events:none}header small{color:#d6b77f;letter-spacing:.24em}header h2{font-size:34px;margin:12px 0}header p{font:15px/1.7 sans-serif;max-width:610px;color:#d7e0dd;text-shadow:0 2px 6px #000}.command-rail{position:absolute;left:4%;top:31%;display:flex;flex-direction:column;gap:15px;width:235px;z-index:5}.command-rail button{cursor:pointer;text-align:left;background:#0a202bbf;border:0;border-left:2px solid #57717c;padding:14px 18px;color:#aebfc3}.command-rail button[aria-pressed=true]{border-color:#edcb85;background:#8a683333;color:#f3dba8}.command-rail b{font:24px SimSun}.command-rail span{display:block;font:12px/1.5 sans-serif;margin-top:7px}.command-rail i{display:block;font:10px sans-serif;margin-top:9px;color:#dbbc78;letter-spacing:.25em}.river-plane{position:absolute;inset:16% 1% 17% 18%;perspective:900px}.far-bank{position:absolute;top:8%;right:14%;font:12px SimSun;letter-spacing:.3em;color:#9eb3b5}.signal-trails{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.signal-trails path{fill:none;stroke:#d7b876;stroke-width:2;stroke-dasharray:7 12;opacity:0;transition:opacity .4s}.signal-trails path.lit{opacity:.45;animation:signal 2s linear infinite}.signal-boat{position:absolute;width:120px;border:0;background:transparent;color:#d2dfdc;cursor:pointer;transform:translate(-50%,-50%);transition:color .3s}.signal-boat svg{width:100%;display:block;filter:drop-shadow(0 14px 8px #0008)}.signal-boat strong{font:14px SimSun}.signal-boat small{display:block;font:11px sans-serif;padding-top:5px}.signal-boat.answered{color:#f3d095}.boat-signal-light{display:block;margin:0 auto 5px;width:15px;height:15px;border:1px solid #e7c477;border-radius:50%;background:#a57b38aa;box-shadow:0 0 25px #edc27488}.answering .boat-signal-light{animation:reply .5s 3}.boat-lamp{filter:drop-shadow(0 0 8px #f9bc66)}.answering .boat-lamp{animation:reply .5s 3}.signal-boat:focus-visible{outline:2px solid #e3c386}.lead-seat{position:absolute;left:77%;top:72%;text-align:center}.lead-seat span{display:block;font-size:12px;color:#d7ba85}.lead-seat small{display:block;font:11px sans-serif;white-space:nowrap}.hooded-lamp{width:55px;height:70px;margin:8px;background:linear-gradient(90deg,#3c3026,#806642,#3b3028);border:3px solid #b59a6d;border-radius:20px 20px 7px 7px;cursor:grab;touch-action:none}.hooded-lamp i{display:block;width:28px;height:37px;margin:auto;background:#e9b960;box-shadow:0 0 23px #ecb35b88;border-radius:7px}.hooded-lamp.flash i{background:#fff3b9;box-shadow:0 0 60px #ffca71}.hooded-lamp.dragging{outline:2px solid #ffe3ab;cursor:grabbing}footer{position:absolute;bottom:0;left:0;right:0;min-height:150px;padding:18px 4% 14px;background:linear-gradient(transparent,#06121ef5 25%);z-index:8;font-family:sans-serif}.signal-channel{display:flex;align-items:center;gap:12px}.signal-channel button{background:none;border:0;border-bottom:1px solid #697b80;color:#afc5c9;font-size:13px;padding:6px 10px;cursor:pointer}.signal-channel button[aria-pressed=true]{color:#f2ce8a;border-color:#f2ce8a}.signal-channel small{font-size:11px;color:#9eb4b9}.signal-instruments{display:flex;align-items:center;gap:12px;margin-top:13px}.signal-instruments button{background:#263d45;border:1px solid #708b8d;padding:12px 19px;color:#e4d9bf;cursor:pointer}.signal-instruments button small{display:block;font:10px sans-serif;margin-top:5px;color:#abc0c4}.signal-instruments .minor{border:0;background:none;font-size:11px;padding:8px;color:#a9bcbf}.code-strip{color:#f0cb86;width:85px;text-align:center;letter-spacing:.2em;font:14px sans-serif}.send-finish{position:absolute;right:4%;bottom:30px;background:#e2c58e;border:1px solid #e8cf9f;padding:16px 22px;color:#162a30;cursor:pointer}.signal-agreement{display:block;font:10px sans-serif;color:#82989d;margin-top:13px}button:disabled{opacity:.35;cursor:default}.still *{animation:none!important;transition:none!important}
@keyframes mist{to{transform:translateX(14%)}}@keyframes signal{to{stroke-dashoffset:-38}}@keyframes reply{50%{opacity:.2}}@media(max-width:950px){header{top:8%;width:90%}header h2{font-size:26px}.command-rail{width:180px;top:32%;gap:6px}.command-rail button{padding:9px 13px}.command-rail b{font-size:19px}.command-rail span{font-size:10px}.river-plane{left:22%;bottom:25%}.signal-boat{width:140px}.send-finish{bottom:12px;padding:11px;font-size:12px}.signal-instruments{gap:3px}.signal-instruments button{padding:9px 11px}.signal-channel small{max-width:220px}.signal-agreement{margin-top:22px}}
@media(max-height:800px){
 header{top:24px}header h2{font-size:30px;margin:8px 0}header p{margin:8px 0;line-height:1.5}
 .command-rail{top:164px;gap:6px}.command-rail button{padding:5px 18px}.command-rail span,.command-rail i{margin-top:4px}
 .river-plane{bottom:185px}.lead-seat{top:auto;bottom:0}
}
</style>
